    "Tek kullan\u0131c\u0131 \xB7 maksimum bir aktif giri\u015F oturumu": [
      "One user \xB7 one active sign-in session",
      "Ein Benutzer \xB7 eine aktive Sitzung",
      "Un utilisateur \xB7 une session active",
      "Un utilizator \xB7 o sesiune activ\u0103",
      "E\xE9n gebruiker \xB7 \xE9\xE9n actieve sessie",
      "Jedan korisnik \xB7 jedna aktivna sesija"
    ],
    "SessionRegistry ayn\u0131 runtime/taray\u0131c\u0131 kimli\u011Finde tek oturum davran\u0131\u015F\u0131n\u0131 uygular. Ger\xE7ek cihazlar aras\u0131 anl\u0131k revoke \xFCretimde merkezi Auth/backend taraf\u0131ndan enforce edilmelidir; bu offline paket cross-device g\xFCvenli\u011Fi VERIFIED saymaz.": [
      "This local session registry controls one browser only. Immediate sign-out across devices needs a central sign-in service. Cross-device security has not been verified.",
      "Diese lokale Sitzungsverwaltung gilt nur f\xFCr einen Browser. Ger\xE4te\xFCbergreifendes Abmelden ben\xF6tigt einen zentralen Anmeldedienst und wurde nicht gepr\xFCft.",
      "Ce registre local contr\xF4le un seul navigateur. La d\xE9connexion entre appareils n\xE9cessite un service central et n\u2019a pas \xE9t\xE9 v\xE9rifi\xE9e.",
      "Registrul local controleaz\u0103 un singur browser. Deconectarea \xEEntre dispozitive necesit\u0103 un serviciu central \u0219i nu a fost verificat\u0103.",
      "Dit lokale register beheert \xE9\xE9n browser. Afmelden op andere apparaten vereist een centrale aanmeldservice en is niet geverifieerd.",
      "Lokalni registar kontroli\u0161e jedan pregleda\u010D. Odjava na drugim ure\u0111ajima zahteva centralnu prijavu i nije proverena."
    ],
    "Ya\u015Fad\u0131\u011F\u0131n\u0131z sorunu k\u0131sa \u015Fekilde yazman\u0131z yeterlidir. Sayfa/oturum/versiyon ve g\xFCvenli teknik log ba\u011Flam\u0131 sistem taraf\u0131ndan otomatik eklenecektir.": [
      "Briefly describe the problem. The system adds the page, session, version and safe technical logs automatically.",
      "Beschreiben Sie das Problem kurz. Seite, Sitzung, Version und sichere technische Protokolle werden automatisch erg\xE4nzt.",
      "D\xE9crivez bri\xE8vement le probl\xE8me. Le syst\xE8me ajoute la page, la session, la version et les journaux techniques s\xFBrs.",
      "Descrie\u021Bi pe scurt problema. Sistemul adaug\u0103 automat pagina, sesiunea, versiunea \u0219i jurnalele tehnice sigure.",
      "Beschrijf het probleem kort. Het systeem voegt pagina, sessie, versie en veilige technische loggegevens toe.",
      "Ukratko opi\u0161ite problem. Sistem automatski dodaje stranicu, sesiju, verziju i bezbedne tehni\u010Dke zapise."
    ],
    "Hata raporu demo olarak haz\u0131rland\u0131. Mail g\xF6nderimi ve sanitized diagnostic payload ger\xE7ek backend entegrasyonunda ba\u011Flanacak.": [
      "This is a demo problem report. Sending email and filtered diagnostics will be connected to the live server later.",
      "Dies ist ein Demo-Fehlerbericht. E-Mail-Versand und bereinigte Diagnosedaten werden sp\xE4ter mit dem Server verbunden.",
      "Ceci est un rapport de d\xE9monstration. L\u2019envoi d\u2019e-mails et de diagnostics filtr\xE9s sera reli\xE9 au serveur ult\xE9rieurement.",
      "Acesta este un raport demonstrativ. Trimiterea e-mailului \u0219i a diagnosticelor filtrate va fi conectat\u0103 ulterior la server.",
      "Dit is een demonstratierapport. E-mail en gefilterde diagnosegegevens worden later met de server verbonden.",
      "Ovo je probni izve\u0161taj o problemu. Slanje e-po\u0161te i filtrirane dijagnostike bi\u0107e povezano sa serverom kasnije."
    ],
