      "Exist\u0103 deja un fi\u0219ier cu acest nume. \xCEncarc\u0103 o versiune nou\u0103 sau folose\u0219te alt nume.",
      "Een bestand met deze naam bestaat al. Upload een nieuwe versie of gebruik een andere naam.",
      "Datoteka sa ovim nazivom ve\u0107 postoji. Otpremite novu verziju ili koristite drugi naziv."
